-- ===== Part 2: row-level security and functions =====
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['connections', 'connection_secrets', 'connection_resource_scopes', 'connection_health', 'sync_runs', 'job_definitions', 'job_executions']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org())',
      t
    );
  END LOOP;
END
$$;

-- Organization of a connection, only when p_user is a member of it; NULL otherwise.
CREATE FUNCTION pcp_resolve_connection_org(p_connection uuid, p_user uuid)
  RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT c.organization_id
    FROM connections c
    JOIN organization_members m ON m.organization_id = c.organization_id AND m.user_id = p_user
    WHERE c.id = p_connection
  $$;

-- Enabled schedules across tenants, for the scheduler role (ADR 0003: no BYPASSRLS for app roles).
CREATE FUNCTION pcp_due_job_definitions()
  RETURNS TABLE (organization_id uuid, id uuid, kind text, entity_id uuid, every_seconds integer)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT d.organization_id, d.id, d.kind, d.entity_id, d.every_seconds
    FROM job_definitions d
    WHERE d.enabled
  $$;

ALTER FUNCTION pcp_resolve_connection_org(uuid, uuid) OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_resolve_connection_org(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_resolve_connection_org(uuid, uuid) TO pcp_app;

ALTER FUNCTION pcp_due_job_definitions() OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_due_job_definitions() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_due_job_definitions() TO pcp_scheduler;
